use actix_web::http::header::HeaderValue;
use actix_web::middleware::DefaultHeaders;

/// The one inline script Expo's static renderer emits on every route.
///
/// The exported HTML is not ours to change (it is generated by
/// `expo export`), so the CSP pins this exact body by hash. The release gate
/// (`apps/client/scripts/check-web-dist.mjs`) recomputes it from `dist/`; if
/// Expo changes the snippet, the build fails and this constant plus
/// `public/_headers` must be updated together.
pub const INLINE_HYDRATE_SCRIPT: &str = "globalThis.__EXPO_ROUTER_HYDRATE__=true;";

/// SHA-256 of [`INLINE_HYDRATE_SCRIPT`], base64, in CSP source form.
/// Keep this in sync with `apps/client/public/_headers`; a Rust test checks
/// both the hash and the `_headers` parity.
pub const INLINE_HYDRATE_SHA256: &str = "sha256-67fhrP0+BkBqmgGGXTtgiVO/9EQs3QruYNU/7fnRkI8=";

/// Least-privilege browser capabilities. `clipboard-write=(self)` is required
/// by the "copy vault id" action (`lib/settings/vault-section.tsx`); nothing
/// else in the app needs device APIs.
pub const PERMISSIONS_POLICY: &str = "accelerometer=(), browsing-topics=(), camera=(), clipboard-read=(), clipboard-write=(self), display-capture=(), geolocation=(), gyroscope=(), hid=(), magnetometer=(), microphone=(), midi=(), payment=(), serial=(), usb=()";

pub const HSTS_VALUE: &str = "max-age=31536000";

/// Response policy for the browser-facing app.
///
/// `https` is a deployment declaration, not something sniffed from a request:
/// the server normally binds loopback HTTP (`main.rs`), and there is no trusted
/// proxy configuration in this repo. HSTS and `upgrade-insecure-requests` are
/// emitted only when the operator sets `VOULT_HTTPS=1`.
#[derive(Debug, Clone, Copy)]
pub struct HeaderPolicy {
    pub https: bool,
}

impl HeaderPolicy {
    pub fn new(https: bool) -> Self {
        Self { https }
    }

    /// The document policy. `default-src 'none'` makes every allowance
    /// explicit; the four non-obvious ones are:
    ///
    /// - `'wasm-unsafe-eval'`: sqlite-wasm compiles `/sqlite/sqlite3.wasm`.
    ///   This is not JS `eval`; the bundle's only `eval` is uuidv4's
    ///   unreachable node fallback, and Zod's `new Function` probe is inside a
    ///   `try/catch` (a CSP block degrades to no JIT, not a crash).
    /// - `style-src 'unsafe-inline'`: Expo's two inline `<style>` blocks and
    ///   React Native Web's runtime style injection. External exfiltration via
    ///   CSS is blocked by `img-src`/`font-src`/`connect-src`.
    /// - `img-src data: blob:`: the favicon cache stores proxied icons as
    ///   `data:image/...;base64` URLs and renders them through `<Image>`.
    /// - `worker-src 'self' blob:`: both SQLite workers are same-origin; the
    ///   blob allowance is for React Native Web's worker helper when
    ///   `crossOriginIsolated` is true.
    pub fn csp(&self) -> String {
        let script_src = format!("script-src 'self' '{INLINE_HYDRATE_SHA256}' 'wasm-unsafe-eval'");
        let mut directives: Vec<String> = vec![
            "default-src 'none'".to_string(),
            script_src,
            "style-src 'self' 'unsafe-inline'".to_string(),
            "img-src 'self' data: blob:".to_string(),
            "font-src 'self'".to_string(),
            "connect-src 'self'".to_string(),
            "worker-src 'self' blob:".to_string(),
            "manifest-src 'self'".to_string(),
            "object-src 'none'".to_string(),
            "frame-src 'none'".to_string(),
            "frame-ancestors 'none'".to_string(),
            "base-uri 'none'".to_string(),
            "form-action 'self'".to_string(),
        ];
        if self.https {
            directives.push("upgrade-insecure-requests".to_string());
        }
        directives.join("; ")
    }

    /// The full header set. Tests and the `_headers` parity check use this as
    /// the single source of truth; `default_headers` applies it to Actix.
    pub fn headers(&self) -> Vec<(&'static str, String)> {
        let mut headers = vec![
            ("Content-Security-Policy", self.csp()),
            ("Cross-Origin-Opener-Policy", "same-origin".to_string()),
            ("Cross-Origin-Embedder-Policy", "require-corp".to_string()),
            ("X-Content-Type-Options", "nosniff".to_string()),
            ("X-Frame-Options", "DENY".to_string()),
            ("Referrer-Policy", "no-referrer".to_string()),
            ("Permissions-Policy", PERMISSIONS_POLICY.to_string()),
        ];
        if self.https {
            headers.push(("Strict-Transport-Security", HSTS_VALUE.to_string()));
        }
        headers
    }
}

/// Build the Actix middleware. Register this **last** on `App` (outermost) so
/// CORS preflights and middleware-generated error responses also receive the
/// headers; Actix's `DefaultHeaders` only fills in headers that are absent, so
/// the favicon's handler-level sandbox CSP is not overwritten.
pub fn default_headers(https: bool) -> DefaultHeaders {
    let mut headers = DefaultHeaders::new();
    for (name, value) in HeaderPolicy::new(https).headers() {
        headers = headers.add((
            name,
            HeaderValue::from_str(&value).expect("security header values are static ASCII"),
        ));
    }
    headers
}

#[cfg(test)]
mod tests {
    use super::*;
    use actix_cors::Cors;
    use actix_web::dev::ServiceResponse;
    use actix_web::http::Method;
    use actix_web::{App, HttpResponse, test as actix_test, web};
    use base64::Engine as _;
    use base64::engine::general_purpose::STANDARD as BASE64_STANDARD;
    use sha2::{Digest, Sha256};
    use std::collections::HashMap;
    use std::fs;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn header<B>(res: &ServiceResponse<B>, name: &str) -> String {
        res.headers()
            .get(name)
            .unwrap_or_else(|| panic!("missing header {name}"))
            .to_str()
            .unwrap()
            .to_string()
    }

    fn assert_policy<B>(res: &ServiceResponse<B>, https: bool) {
        for (name, expected) in HeaderPolicy::new(https).headers() {
            assert_eq!(header(res, name), expected, "header {name}");
        }
    }

    fn csp_directive<'a>(csp: &'a str, name: &str) -> &'a str {
        csp.split(';')
            .map(str::trim)
            .find_map(|part| {
                let (directive, value) = part.split_once(' ').unwrap_or((part, ""));
                (directive == name).then_some(value)
            })
            .unwrap_or("")
    }

    fn parse_headers_file(raw: &str) -> HashMap<String, String> {
        raw.lines()
            .map(str::trim)
            .filter(|line| !line.is_empty() && !line.starts_with('#') && !line.starts_with("/*"))
            .filter_map(|line| line.split_once(':'))
            .map(|(name, value)| (name.trim().to_ascii_lowercase(), value.trim().to_string()))
            .collect()
    }

    #[test]
    fn inline_hash_is_pinned() {
        let digest = Sha256::digest(INLINE_HYDRATE_SCRIPT.as_bytes());
        let expected = format!("sha256-{}", BASE64_STANDARD.encode(digest));
        assert_eq!(expected, INLINE_HYDRATE_SHA256);
    }

    #[test]
    fn csp_is_strict_and_sqlite_compatible() {
        let csp = HeaderPolicy::new(false).csp();
        let script = csp_directive(&csp, "script-src");
        assert!(script.contains("'self'"));
        assert!(script.contains(INLINE_HYDRATE_SHA256));
        assert!(script.contains("'wasm-unsafe-eval'"));
        assert!(!script.contains("'unsafe-inline'"));
        assert!(!script.contains("'unsafe-eval'"));

        let style = csp_directive(&csp, "style-src");
        assert!(style.contains("'self'"));
        assert!(style.contains("'unsafe-inline'"));

        let img = csp_directive(&csp, "img-src");
        assert!(img.contains("'self'"));
        assert!(img.contains("data:"));
        assert!(img.contains("blob:"));

        let worker = csp_directive(&csp, "worker-src");
        assert!(worker.contains("'self'"));
        assert!(worker.contains("blob:"));

        assert_eq!(csp_directive(&csp, "default-src"), "'none'");
        assert_eq!(csp_directive(&csp, "connect-src"), "'self'");
        assert_eq!(csp_directive(&csp, "font-src"), "'self'");
        assert_eq!(csp_directive(&csp, "frame-ancestors"), "'none'");
        assert_eq!(csp_directive(&csp, "base-uri"), "'none'");
        assert_eq!(csp_directive(&csp, "form-action"), "'self'");
        assert!(
            !csp.split(';')
                .any(|d| d.trim() == "upgrade-insecure-requests")
        );
    }

    #[test]
    fn coop_coep_are_exact() {
        let headers: HashMap<_, _> = HeaderPolicy::new(false)
            .headers()
            .into_iter()
            .map(|(name, value)| (name.to_ascii_lowercase(), value))
            .collect();
        assert_eq!(
            headers
                .get("cross-origin-opener-policy")
                .map(String::as_str),
            Some("same-origin")
        );
        assert_eq!(
            headers
                .get("cross-origin-embedder-policy")
                .map(String::as_str),
            Some("require-corp")
        );
    }

    #[test]
    fn hsts_and_upgrade_are_tls_only() {
        let http = HeaderPolicy::new(false).headers();
        assert!(
            !http
                .iter()
                .any(|(name, _)| *name == "Strict-Transport-Security")
        );
        assert!(
            !HeaderPolicy::new(false)
                .csp()
                .split(';')
                .any(|d| d.trim() == "upgrade-insecure-requests")
        );

        let tls = HeaderPolicy::new(true).headers();
        assert!(
            tls.iter()
                .any(|(name, value)| *name == "Strict-Transport-Security" && value == HSTS_VALUE)
        );
        assert!(
            HeaderPolicy::new(true)
                .csp()
                .split(';')
                .any(|d| d.trim() == "upgrade-insecure-requests")
        );
    }

    #[test]
    fn static_headers_file_matches_tls_policy() {
        // Compiled into the test binary; the path is relative to this source
        // file. This is the drift guard between the Rust policy and the static
        // host mirror.
        let actual = parse_headers_file(include_str!("../../client/public/_headers"));
        let expected: HashMap<_, _> = HeaderPolicy::new(true)
            .headers()
            .into_iter()
            .map(|(name, value)| (name.to_ascii_lowercase(), value))
            .collect();
        assert_eq!(actual, expected);
    }

    #[actix_web::test]
    async fn headers_are_applied_to_routes() {
        let app = actix_test::init_service(
            App::new()
                .wrap(default_headers(false))
                .service(web::resource("/").to(|| async { HttpResponse::Ok().body("ok") })),
        )
        .await;

        let res =
            actix_test::call_service(&app, actix_test::TestRequest::get().uri("/").to_request())
                .await;
        assert_eq!(res.status(), 200);
        assert_policy(&res, false);

        let res = actix_test::call_service(
            &app,
            actix_test::TestRequest::get().uri("/missing").to_request(),
        )
        .await;
        assert_eq!(res.status(), 404);
        assert_policy(&res, false);

        let res = actix_test::call_service(
            &app,
            actix_test::TestRequest::default()
                .method(Method::OPTIONS)
                .uri("/")
                .to_request(),
        )
        .await;
        assert_policy(&res, false);
    }

    #[actix_web::test]
    async fn cors_preflight_still_gets_security_headers() {
        // Mirrors main.rs ordering: CORS wraps the service, then the security
        // policy wraps CORS (outermost), so a short-circuited preflight still
        // receives COOP/COEP/CSP.
        let cors = Cors::default()
            .allowed_origin("http://example.com")
            .supports_credentials()
            .allow_any_method()
            .allow_any_header();
        let app = actix_test::init_service(
            App::new()
                .wrap(cors)
                .wrap(default_headers(false))
                .service(web::resource("/").to(|| async { HttpResponse::Ok().body("ok") })),
        )
        .await;

        let request = actix_test::TestRequest::default()
            .method(Method::OPTIONS)
            .uri("/")
            .insert_header(("Origin", "http://example.com"))
            .insert_header(("Access-Control-Request-Method", "GET"))
            .to_request();
        let res = actix_test::call_service(&app, request).await;
        assert!(res.status().is_success());
        assert_eq!(
            header(&res, "access-control-allow-origin"),
            "http://example.com"
        );
        assert_policy(&res, false);
    }

    #[actix_web::test]
    async fn static_html_gets_headers() {
        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let dir = std::env::temp_dir().join(format!(
            "voult-security-headers-{}-{unique}",
            std::process::id()
        ));
        fs::create_dir_all(&dir).unwrap();
        fs::write(
            dir.join("index.html"),
            "<!doctype html><html><body>ok</body></html>",
        )
        .unwrap();

        let app = actix_test::init_service(App::new().wrap(default_headers(false)).service(
            crate::static_site::static_site(dir.to_string_lossy().as_ref()),
        ))
        .await;

        let res =
            actix_test::call_service(&app, actix_test::TestRequest::get().uri("/").to_request())
                .await;
        assert!(res.status().is_success());
        assert!(header(&res, "content-type").starts_with("text/html"));
        assert_policy(&res, false);

        fs::remove_dir_all(&dir).ok();
    }
}
